pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 base;
    Maker maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        base = new MockERC20();
        maker = new Maker();
    }

    function testFuzz_property(
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce
    ) public {
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 9_000 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(base),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1_000_000,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory signature = new bytes(65);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 expected = block.timestamp + duration;
        uint256 key = isLong ? uint256(c.hashOrder(order)) : uint256(c.hashOppositeOrder(order));

        c.fillOrder(order, signature, floorAssetTokenIds);

        assertTrue(c.positionExpirations(key) == expected);
    }
}

